sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform shader blurred;
uniform float blur;
uniform float angle;
uniform float depth;
uniform float intensity;
layout(color) uniform half4 highlight;
layout(color) uniform half4 shadow;
half4 main(float2 coord) {
    half4 src = image.eval(coord);
    if (src.a <= 0.0 || blur <= 0.0) return src;
    float s = max(blur * 0.2, 1.0);
    float dx = float(blurred.eval(coord + float2(s, 0.0)).a - blurred.eval(coord - float2(s, 0.0)).a);
    float dy = float(blurred.eval(coord + float2(0.0, s)).a - blurred.eval(coord - float2(0.0, s)).a);
    float3 n = normalize(float3(-dx * depth * 4.0, -dy * depth * 4.0, 1.0));
    float a = radians(angle);
    float3 l = normalize(float3(cos(a), -sin(a), 0.8));
    float lit = dot(n, l) - l.z;
    float3 base = float3(src.rgb) / float(src.a);
    float k = clamp(intensity, 0.0, 1.0);
    float3 rgb = lit > 0.0 ? mix(base, float3(highlight.rgb), clamp(lit * 2.0, 0.0, 1.0) * k * float(highlight.a))
                           : mix(base, float3(shadow.rgb), clamp(-lit * 2.0, 0.0, 1.0) * k * float(shadow.a));
    return half4(half3(rgb) * src.a, src.a);
}
